using Jellyfin.Plugin.WatchlistTracker.Models; using Jellyfin.Plugin.WatchlistTracker.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using MediaBrowser.Controller.Net;
namespace Jellyfin.Plugin.WatchlistTracker.Api;
[ApiController,Authorize,Route("WatchlistTracker")] public sealed class WatchlistController : ControllerBase, IController { readonly WatchlistService s; public WatchlistController(WatchlistService service)=>s=service; [HttpGet("All")] public Task<List<WatchedEpisode>> All()=>s.GetAllAsync(); [HttpGet("Series")] public Task<List<string>> Series()=>s.GetAllSeriesAsync(); [HttpGet("Statistics")] public Task<object> Statistics()=>s.GetStatisticsAsync(); [HttpGet("IsWatched")] public async Task<ActionResult<WatchedEpisode?>> IsWatched(string series,int season,int episode)=>Ok(await s.GetBySeriesAndEpisodeAsync(series,season,episode)); [HttpPost("MarkWatched")] public async Task<ActionResult<WatchedEpisode>> MarkWatched(WatchedEpisode x)=>Ok(await s.AddOrUpdateAsync(x)); [HttpDelete("{id:long}")] public async Task<IActionResult> Delete(long id){await s.DeleteAsync(id);return NoContent();} [HttpGet("ui"),AllowAnonymous] public ContentResult Ui()=>Content("<!doctype html><meta charset='utf-8'><iframe src='/WatchlistTracker/web/watchlist.html' style='position:fixed;inset:0;width:100%;height:100%;border:0'></iframe>","text/html"); }
